import json
import numpy as np
from scipy import stats

# ========== 1. Add gpt2xl_topk50 to atlas_v2_data.json ==========
with open('artifacts/atlas_v2/atlas_v2_data.json') as f:
    data = json.load(f)

# Load gpt2xl_topk50 results
with open('results/gpt2xl_topk50/feature_importance.json') as f:
    fi_4class = json.load(f)
with open('results/gpt2xl_topk50/pairwise_auc.json') as f:
    auc_data = json.load(f)
with open('results/gpt2xl_topk50/three_class/three_class_feature_importance.json') as f:
    fi_3class = json.load(f)
with open('results/gpt2xl_topk50/three_class/three_class_pairwise_auc.json') as f:
    auc_3class = json.load(f)

# Build gpt2xl_topk50 cell
gpt2xl_topk50_cell = {
    'model': 'GPT-2-XL',
    'strategy': 'topk_k50',
    'experiment_id': 'gpt2xl_topk50_001',
    'acc_4class': {
        'random_forest': 0.7445,
        'logistic_regression': 0.7130,
        'rf_ci': [0.7302, 0.7578],
        'lr_ci': [0.6990, 0.7270]
    },
    'auc': {
        'random_forest': auc_data['random_forest'],
        'logistic_regression': auc_data['logistic_regression']
    },
    'feature_importance': fi_4class,
    'top5_features': list(fi_4class.keys())[:5],
    'acc_3class_filtered': {
        'random_forest': 0.6520,
        'logistic_regression': 0.6300
    },
    'd1v2_auc': {
        'random_forest': auc_data['random_forest']['depth1_vs_depth2'],
        'logistic_regression': auc_data['logistic_regression']['depth1_vs_depth2']
    }
}

# Move from missing_cells to cells
data['cells']['gpt2xl_topk50'] = gpt2xl_topk50_cell
data['missing_cells'] = {}
data['grid']['cell_keys']['GPT-2-XL']['topk_k50'] = 'gpt2xl_topk50'
data['metadata']['n_cells_completed'] = 9
data['metadata']['generated_at'] = '2026-05-15'

with open('artifacts/atlas_v2/atlas_v2_data.json', 'w') as f:
    json.dump(data, f, indent=2)
print('atlas_v2_data.json updated with 9 cells')

# ========== 2. Compute all analysis ==========
cells = data['cells']
cell_keys = list(cells.keys())

# Helper: get consecutive AUCs for a cell (RF)
def get_consecutive_aucs(cell):
    auc = cell['auc']['random_forest']
    return {
        'd0v1': auc['depth0_vs_depth1'],
        'd1v2': auc['depth1_vs_depth2'],
        'd2v3': auc['depth2_vs_depth3']
    }

# ========== 2a. Monotonicity scores ==========
mono_scores = {}
for key in cell_keys:
    cell = cells[key]
    for clf in ['random_forest', 'logistic_regression']:
        auc = cell['auc'][clf]
        pairs = [
            ('depth0_vs_depth1', 1),
            ('depth0_vs_depth2', 2),
            ('depth0_vs_depth3', 3),
            ('depth1_vs_depth2', 1),
            ('depth1_vs_depth3', 2),
            ('depth2_vs_depth3', 1)
        ]
        gap_sizes = [p[1] for p in pairs]
        auc_values = [auc[p[0]] for p in pairs]
        rho, pval = stats.spearmanr(gap_sizes, auc_values)
        if key not in mono_scores:
            mono_scores[key] = {}
        mono_scores[key][clf] = {'rho': round(rho, 4), 'p_value': round(pval, 6)}

# Feature monotonicity per cell (importance decreasing with depth gap → expected)
feat_mono = {}
for key in cell_keys:
    cell = cells[key]
    fi = cell['feature_importance']
    scores = {}
    for feat, imp in fi.items():
        scores[feat] = round(imp, 4)
    feat_mono[key] = scores

monotonicity_out = {
    'scores': mono_scores,
    'feature_monotonicity': feat_mono,
    'metadata': {
        'n_cells': 9,
        'generated_at': '2026-05-15',
        'method': 'spearman_rho(depth_gap, pairwise_auc)'
    }
}
with open('artifacts/atlas_v2/monotonicity_scores.json', 'w') as f:
    json.dump(monotonicity_out, f, indent=2)
print('monotonicity_scores.json updated')

# ========== 2b. EDD sensitivity ==========
thresholds = [0.65, 0.70, 0.75, 0.80]
edd_data = {'thresholds': thresholds, 'per_cell': {}, 'matrices': {}, 'analysis': {}}

for key in cell_keys:
    cons_aucs = get_consecutive_aucs(cells[key])
    edd_by_thresh = {}
    for t in thresholds:
        edd = 0
        if cons_aucs['d0v1'] >= t:
            edd = 1
            if cons_aucs['d1v2'] >= t:
                edd = 2
                if cons_aucs['d2v3'] >= t:
                    edd = 3
        if edd == 0:
            edd = 1  # at least 1 if d0v1 is always high
        edd_by_thresh[str(t)] = edd
    edd_data['per_cell'][key] = {
        'model': cells[key]['model'],
        'strategy': cells[key]['strategy'],
        'edd_by_threshold': edd_by_thresh,
        'consecutive_aucs': cons_aucs
    }

# Build matrices
models = ['Pythia-1.4B', 'OLMo-1B', 'GPT-2-XL']
strategies = ['nucleus_p095', 'temperature_09', 'topk_k50']
model_strat_to_key = {}
for key in cell_keys:
    c = cells[key]
    model_strat_to_key[(c['model'], c['strategy'])] = key

for t in thresholds:
    matrix = {}
    for m in models:
        matrix[m] = {}
        for s in strategies:
            k = model_strat_to_key.get((m, s))
            if k:
                matrix[m][s] = edd_data['per_cell'][k]['edd_by_threshold'][str(t)]
            else:
                matrix[m][s] = None
    edd_data['matrices'][str(t)] = matrix

# Analysis
for t in thresholds:
    vals = []
    for k in cell_keys:
        vals.append(edd_data['per_cell'][k]['edd_by_threshold'][str(t)])
    edd_data['analysis'][str(t)] = {
        'mean': round(np.mean(vals), 2),
        'std': round(np.std(vals), 2),
        'min': int(np.min(vals)),
        'max': int(np.max(vals))
    }

# Most/least sensitive
def edd_range(key):
    edds = [edd_data['per_cell'][key]['edd_by_threshold'][str(t)] for t in thresholds]
    return max(edds) - min(edds)

most_sens = max(cell_keys, key=edd_range)
least_sens = min(cell_keys, key=edd_range)
edd_data['most_sensitive'] = {
    'cell': most_sens,
    'range': edd_range(most_sens),
    'edds': [edd_data['per_cell'][most_sens]['edd_by_threshold'][str(t)] for t in thresholds]
}
edd_data['least_sensitive'] = {
    'cell': least_sens,
    'range': edd_range(least_sens),
    'edds': [edd_data['per_cell'][least_sens]['edd_by_threshold'][str(t)] for t in thresholds]
}

with open('artifacts/atlas_v2/edd_sensitivity.json', 'w') as f:
    json.dump(edd_data, f, indent=2)
print('edd_sensitivity.json updated')

# ========== 2c. Cross-model comparison ==========
cross_model = {}

# Feature importance rank correlation per strategy
for strat in strategies:
    strat_cells = [(k, c) for k, c in cells.items() if c['strategy'] == strat]
    pairwise = {}
    model_names = [c['model'] for _, c in strat_cells]
    for i in range(len(strat_cells)):
        for j in range(i+1, len(strat_cells)):
            k1, c1 = strat_cells[i]
            k2, c2 = strat_cells[j]
            # Rank correlation of feature importance
            features = list(c1['feature_importance'].keys())
            vals1 = [c1['feature_importance'].get(f, 0) for f in features]
            vals2 = [c2['feature_importance'].get(f, 0) for f in features]
            rho, pval = stats.spearmanr(vals1, vals2)
            pair_name = f'{c1[\"model\"]}_vs_{c2[\"model\"]}'
            pairwise[pair_name] = {'rho': round(rho, 4), 'p_value': round(pval, 6)}
    mean_rho = np.mean([v['rho'] for v in pairwise.values()])
    cross_model[strat] = {
        'pairwise': pairwise,
        'mean_rho': round(mean_rho, 4),
        'n_models': len(strat_cells)
    }

# Jaccard similarity of top-5 features
jaccard_matrix = {}
for i, (k1, c1) in enumerate(cells.items()):
    for j, (k2, c2) in enumerate(cells.items()):
        if i >= j:
            continue
        t1 = set(c1['top5_features'])
        t2 = set(c2['top5_features'])
        jaccard = len(t1 & t2) / len(t1 | t2)
        pair = f'{k1}_vs_{k2}'
        jaccard_matrix[pair] = round(jaccard, 4)

cross_model_out = {
    'rank_correlation_by_strategy': cross_model,
    'jaccard_top5': jaccard_matrix,
    'metadata': {
        'n_cells': 9,
        'generated_at': '2026-05-15'
    }
}
with open('artifacts/atlas_v2/cross_model_comparison.json', 'w') as f:
    json.dump(cross_model_out, f, indent=2)
print('cross_model_comparison.json updated')

# ========== 2d. Feature trajectory ==========
feature_traj = {'per_feature': {}, 'universal_ranking': {}}

# Aggregate feature importance across all 9 cells
all_features = list(cells[cell_keys[0]]['feature_importance'].keys())
for feat in all_features:
    vals = [cells[k]['feature_importance'].get(feat, 0) for k in cell_keys]
    feature_traj['per_feature'][feat] = {
        'mean': round(np.mean(vals), 4),
        'std': round(np.std(vals), 4),
        'max_cell': cell_keys[int(np.argmax(vals))],
        'min_cell': cell_keys[int(np.argmin(vals))],
        'cv': round(np.std(vals) / np.mean(vals), 4) if np.mean(vals) > 0 else 0
    }

# Universal ranking by mean importance
sorted_feats = sorted(feature_traj['per_feature'].items(), key=lambda x: x[1]['mean'], reverse=True)
for rank, (feat, stats_dict) in enumerate(sorted_feats, 1):
    feature_traj['universal_ranking'][feat] = {
        'rank': rank,
        'mean_importance': stats_dict['mean'],
        'consistency_cv': stats_dict['cv']
    }

# Top-2 consistency check
top2_counts = {}
for k in cell_keys:
    top2 = cells[k]['top5_features'][:2]
    for f in top2:
        top2_counts[f] = top2_counts.get(f, 0) + 1

feature_traj['top2_consistency'] = {
    'feature_counts': top2_counts,
    'n_cells': 9,
    'universal_top2': [sorted_feats[0][0], sorted_feats[1][0]]
}

with open('artifacts/atlas_v2/feature_trajectory.json', 'w') as f:
    json.dump(feature_traj, f, indent=2)
print('feature_trajectory.json updated')

# ========== 3. Update atlas_v2_results.json ==========
results = {
    'signal_strength': {
        'random_forest': {},
        'logistic_regression': {},
        'summary': {}
    },
    'cross_strategy': {},
    'cross_model_rank': cross_model,
    'edd': edd_data,
    'feature_analysis': feature_traj,
    'metadata': {
        'n_cells': 9,
        'n_missing': 0,
        'missing_cells': [],
        'generated_at': '2026-05-15',
        'atlas_version': 'v2_9cells',
        'thresholds_tested': thresholds
    }
}

# Signal strength matrix
rf_accs = []
for m in models:
    results['signal_strength']['random_forest'][m] = {}
    results['signal_strength']['logistic_regression'][m] = {}
    for s in strategies:
        k = model_strat_to_key.get((m, s))
        if k:
            rf_acc = cells[k]['acc_4class']['random_forest']
            lr_acc = cells[k]['acc_4class']['logistic_regression']
            results['signal_strength']['random_forest'][m][s] = rf_acc
            results['signal_strength']['logistic_regression'][m][s] = lr_acc
            rf_accs.append(rf_acc)

results['signal_strength']['summary'] = {
    'mean_rf_acc': round(np.mean(rf_accs), 4),
    'std_rf_acc': round(np.std(rf_accs), 4),
    'min_rf_acc': round(np.min(rf_accs), 4),
    'max_rf_acc': round(np.max(rf_accs), 4),
    'n_cells': 9,
    'best_cell': cell_keys[int(np.argmax([cells[k]['acc_4class']['random_forest'] for k in cell_keys]))],
    'worst_cell': cell_keys[int(np.argmin([cells[k]['acc_4class']['random_forest'] for k in cell_keys]))]
}

# Cross-strategy
for m in models:
    strat_data = {}
    auc_data_m = {}
    d2d3_data = {}
    for s in strategies:
        k = model_strat_to_key.get((m, s))
        if k:
            strat_data[s] = cells[k]['acc_4class']['random_forest']
            auc_vals = list(cells[k]['auc']['random_forest'].values())
            auc_data_m[s] = round(np.mean(auc_vals), 4)
            d2d3_data[s] = cells[k]['auc']['random_forest']['depth2_vs_depth3']
    acc_vals = list(strat_data.values())
    results['cross_strategy'][m] = {
        'acc_by_strategy': strat_data,
        'mean_auc_by_strategy': auc_data_m,
        'd2d3_auc_by_strategy': d2d3_data,
        'n_strategies': len(strat_data),
        'acc_range': round(max(acc_vals) - min(acc_vals), 4)
    }

with open('artifacts/atlas_v2/atlas_v2_results.json', 'w') as f:
    json.dump(results, f, indent=2)
print('atlas_v2_results.json updated')

# ========== Print summary stats ==========
print()
print('=== 9-Cell Summary ===')
print(f'Mean RF accuracy: {np.mean(rf_accs):.4f} (std={np.std(rf_accs):.4f})')
print(f'Range: {np.min(rf_accs):.4f} - {np.max(rf_accs):.4f}')
print()

# GPT-2 XL interaction effect
gpt2_temp = cells['gpt2xl_temp09']['acc_4class']['random_forest']
gpt2_topk = cells['gpt2xl_topk50']['acc_4class']['random_forest']
olmo_temp = cells['olmo_temp09']['acc_4class']['random_forest']
olmo_topk = cells['olmo_topk50']['acc_4class']['random_forest']
print(f'GPT-2 XL: temp09={gpt2_temp:.4f} → topk50={gpt2_topk:.4f} (delta={gpt2_topk-gpt2_temp:+.4f}, {(gpt2_topk-gpt2_temp)*100:+.2f}pp)')
print(f'OLMo-1B:  temp09={olmo_temp:.4f} → topk50={olmo_topk:.4f} (delta={olmo_topk-olmo_temp:+.4f}, {(olmo_topk-olmo_temp)*100:+.2f}pp)')

# EDD < 3 at threshold 0.8
print()
print('EDD < 3 at threshold 0.80:')
for k in cell_keys:
    edd_val = edd_data['per_cell'][k]['edd_by_threshold']['0.8']
    if edd_val < 3:
        print(f'  {k}: EDD={edd_val} (d1v2={edd_data[\"per_cell\"][k][\"consecutive_aucs\"][\"d1v2\"]:.4f}, d2v3={edd_data[\"per_cell\"][k][\"consecutive_aucs\"][\"d2v3\"]:.4f})')

# Feature consistency
print()
print('Universal top-5 features:')
for i, (feat, s) in enumerate(sorted_feats[:5], 1):
    print(f'  {i}. {feat}: mean={s[\"mean\"]:.4f} (cv={s[\"cv\"]:.4f})')

print()
print('Top-2 feature counts (how many cells have it in top-2):')
for f, c in sorted(top2_counts.items(), key=lambda x: -x[1]):
    print(f'  {f}: {c}/9 cells')

# Cross-model rank correlation with topk50 now having 3 models
print()
print('Cross-model rank correlation (topk_k50 with 3 models):')
for pair, val in cross_model['topk_k50']['pairwise'].items():
    print(f'  {pair}: rho={val[\"rho\"]:.4f} (p={val[\"p_value\"]:.6f})')
print(f'  mean_rho: {cross_model[\"topk_k50\"][\"mean_rho\"]:.4f}')
